<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;use App\Models\AccountNotificationSetting;use Illuminate\Http\Request;
class AccountNotificationController extends Controller {public function show(Request $r){return ['success'=>true,'data'=>$this->setting($r)];}public function update(Request $r){$d=$r->validate(['email_enabled'=>'boolean','phone_enabled'=>'boolean','in_app_enabled'=>'boolean','recipients'=>'array','recipients.*.name'=>'required|string','recipients.*.email'=>'nullable|email','recipients.*.phone'=>'nullable|string|max:40','recipients.*.email_enabled'=>'boolean','recipients.*.phone_enabled'=>'boolean','recipients.*.in_app_enabled'=>'boolean','preferences'=>'array','preferences.*.key'=>'required|string','preferences.*.label'=>'required|string','preferences.*.email'=>'boolean','preferences.*.phone'=>'boolean','preferences.*.in_app'=>'boolean']);$s=$this->setting($r);$s->fill($d+['updated_by'=>$r->user()->id])->save();return ['success'=>true,'data'=>$s->fresh(),'message'=>'Notification settings saved.'];}private function setting(Request $r){$u=$r->user();abort_if((int)$u->project_id<1,404,'No project is assigned to this user.');$s=AccountNotificationSetting::firstOrCreate(['project_id'=>$u->project_id,'user_id'=>$u->id],['email_enabled'=>true,'phone_enabled'=>true,'in_app_enabled'=>true,'recipients'=>$this->recipients($u),'preferences'=>$this->preferences(),'inserted_by'=>$u->id,'updated_by'=>$u->id]);if(empty($s->preferences))$s->update(['preferences'=>$this->preferences()]);if(empty($s->recipients))$s->update(['recipients'=>$this->recipients($u)]);return $s->fresh();}private function recipients($u){return [['name'=>'Company Director','email'=>'','phone'=>'','email_enabled'=>true,'phone_enabled'=>true,'in_app_enabled'=>true],['name'=>'Accounting','email'=>'','phone'=>'','email_enabled'=>true,'phone_enabled'=>true,'in_app_enabled'=>true],['name'=>'System Admin','email'=>$u->email,'phone'=>$u->phone,'email_enabled'=>true,'phone_enabled'=>true,'in_app_enabled'=>true],['name'=>'Current User','email'=>$u->email,'phone'=>$u->phone,'email_enabled'=>true,'phone_enabled'=>true,'in_app_enabled'=>true]];}private function preferences(){return collect(['Upcoming Bill Payment','Upcoming Charge – 3-Day Reminder','Payment Successful','Invoice or Receipt Available','Payment Failed or Past Due','Payment Method Expiring','Account Suspension Warning','Account Suspended or Deactivated','Account Reactivated','Login from New Device','Failed Login or Access Attempt','Password, PIN or 2FA Changed','Account or Company Profile Changed','Service Plan or Licence Changed','User Licence Limit Reached','New Message or Support Update','Scheduled Maintenance or Service Outage','Marketing & Special Offers'])->map(fn($x)=>['key'=>str($x)->slug('_')->toString(),'label'=>$x,'email'=>true,'phone'=>$x!=='Marketing & Special Offers','in_app'=>true])->all();}}
